ACTIVE_SUBSCRIPTION_NOT_FOUND = "\u0627\u0634\u062a\u0631\u0627\u06a9 \u0641\u0639\u0627\u0644\u06cc \u067e\u06cc\u062f\u0627 \u0646\u0634\u062f."
